edAt, err = time.Parse(time.RFC3339Nano, updatedAt)\\n\\tif err != nil {\\n\\t\\treturn Todo{}, fmt.Errorf(\"parse todo updated time: %w\", err)\\n\\t}\\n\\ttodo.Completed = completed != 0\\n\\treturn todo, nil\\n}\\n\\nfunc newAPIHandler(store *Store) http.Handler {\\n\\tmux := http.NewServeMux()\\n\\tmux.HandleFunc(\"GET /api/todos\", func(w http.ResponseWriter, _ *http.Request) {\\n\\t\\ttodos, err := store.List()\\n\\t\\tif err != nil {\\n\\t\\t\\twriteError(w, http.StatusInternalServerError, \"could not list todos\")\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\twriteJSON(w, http.StatusOK, todos)\\n\\t})\\n\\tmux.HandleFunc(\"GET /api/todos/{id}\", func(w http.ResponseWriter, r *http.Request) {\\n\\t\\tid, ok := readID(w, r)\\n\\t\\tif !ok {\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\ttodo, err := store.Get(id)\\n\\t\\tif err != nil {\\n\\t\\t\\twriteError(w, http.StatusNotFound, err.Error())\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\twriteJSON(w, http.StatusOK, todo)\\n\\t})\\n\\tmux.HandleFunc(\"POST /api/todos\", func(w http.ResponseWriter, r *http.Request) {\\n\\t\\tvar input todoInput\\n\\t\\tif !readJSON(w, r, &input) {\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\ttodo, err := store.Create(input)\\n\\t\\tif err != nil {\\n\\t\\t\\twriteError(w, http.StatusBadRequest, err.Error())\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\twriteJSON(w, http.StatusCreated, todo)\\n\\t})\\n\\tmux.HandleFunc(\"PUT /api/todos/{id}\", func(w http.ResponseWriter, r *http.Request) {\\n\\t\\tid, ok := readID(w, r)\\n\\t\\tif !ok {\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\tvar input todoInput\\n\\t\\tif !readJSON(w, r, &input) {\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\ttodo, err := store.Update(id, input)\\n\\t\\tif errors.Is(err, errTodoNotFound) {\\n\\t\\t\\twriteError(w, http.StatusNotFound, err.Error())\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\tif err != nil {\\n\\t\\t\\twriteError(w, http.StatusBadRequest, err.Error())\\n\\t\\t\\treturn\\n\\t\\t}\\n\\t\\twriteJSON(w, http.St"}}, {"event_index": 55, "elapsed_seconds": 5.889367, "phase